<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $order = App\Models\Order::where("payment_status", "settlement")->orderBy("id", "desc")->first(); if ($order) { echo json_encode(["order_id" => $order->id, "order_number" => $order->order_number, "payment_status" => $order->payment_status, "status" => $order->status, "invoice_id" => $order->invoice_id]) . "\n"; } else { echo "No settled orders.\n"; } ?>
